def gen(rng):
    def fmt(xs):
        return str(len(xs)) + '\n' + ' '.join(map(str, xs))
    tests = [fmt([0]), fmt([1]), fmt([2]), fmt([3]), fmt([4]), fmt([10**9]), fmt([2**29 + 1, 2**29 + 2, 2**29 + 3]),
             fmt([4, 9, 7]), fmt([0, 1024]), fmt([5, 6, 8, 12, 15, 16])]
    for _ in range(30):
        n = rng.randint(1, 12)
        hi = rng.choice([7, 100, 10**6, 10**9])
        tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(0, 3) for _ in range(100000)]))
    tests.append(fmt([10**9 - rng.randint(0, 5) for _ in range(100000)]))
    return tests

